te;\n            border: none;\n            padding: 8px 14px;\n            border-radius: 8px;\n            font-weight: 600;\n            cursor: pointer;\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            gap: 6px;\n            transition: all 0.2s;\n        }\n        .btn-ui:hover {\n            background: #86198f;\n            transform: translateY(-1px);\n        }\n        \n    </style>\n</head>\n<body>\n    <div class=\"figma-window\">\n        <div class=\"figma-toolbar\">\n            <span><i class=\"fa-brands fa-figma text-warning me-1\"></i> User Flow Diagram</span>\n            <span style=\"color:#10b981; font-size:0.7rem;\"><i class=\"fa-solid fa-play\"></i> 100% Zoom</span>\n        </div>\n        <div class=\"figma-canvas\">\n            \n                <div class=\"card-ui\" style=\"text-align:center;\">\n                    <div style=\"background:#e0f2fe; color:#0284c7; padding:6px; border-radius:6px; font-size:0.75rem; font-weight:bold;\">\n                        1. Pilih Jalur Ujian (exam.php)\n                    </div>\n                    <i class=\"fa-solid fa-arrow-down text-muted my-1\"></i>\n                    <div style=\"background:#fef3c7; color:#b45309; padding:6px; border-radius:6px; font-size:0.75rem; font-weight:bold;\">\n                        2. Kerjakan 25 Soal (Timer 30 Menit)\n                    </div>\n                    <i class=\"fa-solid fa-arrow-down text-muted my-1\"></i>\n                    <div style=\"background:#dcfce7; color:#15803d; padding:6px; border-radius:6px; font-size:0.75rem; font-weight:bold;\">\n                        3. Skor >= 80% -> Generate Sertifikat QR\n                    </div>\n                </div>\n                \n        </div>\n    </div>\n    <script></script>\n</body>\n</html>",
