te;\n            border: none;\n            padding: 8px 14px;\n            border-radius: 8px;\n            font-weight: 600;\n            cursor: pointer;\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            gap: 6px;\n            transition: all 0.2s;\n        }\n        .btn-ui:hover {\n            background: #86198f;\n            transform: translateY(-1px);\n        }\n        \n    </style>\n</head>\n<body>\n    <div class=\"figma-window\">\n        <div class=\"figma-toolbar\">\n            <span><i class=\"fa-brands fa-figma text-warning me-1\"></i> Sitemap Architecture</span>\n            <span style=\"color:#10b981; font-size:0.7rem;\"><i class=\"fa-solid fa-play\"></i> 100% Zoom</span>\n        </div>\n        <div class=\"figma-canvas\">\n            \n                <div class=\"card-ui\">\n                    <strong style=\"color:#a21caf; font-size:0.8rem; display:block; margin-bottom:6px;\">Root: academy.skillance.cloud</strong>\n                    <ul style=\"font-size:0.75rem; color:#475569; margin:0; padding-left:18px; line-height:1.7;\">\n                        <li><strong>/index.php</strong> (Beranda & Katalog Modul)</li>\n                        <li><strong>/roadmap.php</strong> (Jalur Karier Terstruktur)</li>\n                        <li><strong>/learn.php</strong> (Modul Koding & Code Lab)</li>\n                        <li><strong>/projects.php</strong> (Kit Proyek & E-Book)</li>\n                        <li><strong>/exam.php</strong> (Ujian Sertifikasi SKPI)</li>\n                        <li><strong>/verify.php</strong> (Validasi QR Code Resmi)</li>\n                    </ul>\n                </div>\n                \n        </div>\n    </div>\n    <script></script>\n</body>\n</html>",
